        for (int i = 0; i < n; i++) a[i] = sc.nextInt();

        int k = sc.nextInt();
        int lo = 0;
        int hi = n - 1;
        int steps = 0;
        while (lo <= hi) {
            steps++;
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == k) {
