for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];

int sum = pre[r + 1] - pre[l];                    // a[l..r] inclusive
// check: l = 0, r = n-1  ->  pre[n] - pre[0]  =  the whole total

// --- 2D prefix sums -----------------------------------------------------
