            if (a[i] <= b[j]) {
                out[w] = a[i];
                i++;
            } else {
                out[w] = b[j];
                j++;
            }
            w++;
        }
        while (i < n) {
            out[w] = a[i];
            i++;
            w++;
        }
        while (j < m) {
            out[w] = b[j];
            j++;
            w++;
        }
        System.out.println(Arrays.toString(out));
    }
}

