        int sum = 0;
        int best = 0;
        for (int hi = 0; hi < n; hi++) {
            sum += a[hi];
            while (sum >= t) {
                int width = hi - lo + 1;
                if (best == 0 || width < best) {
                    best = width;
                }
                sum -= a[lo];
                lo++;
            }
        }
        System.out.println(best);
    }
}

