import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        String t = sc.next();

        boolean same = s.length() == t.length();
        if (same) {
            int[] freq = new int[26];
            for (int i = 0; i < s.length(); i++) {
                freq[s.charAt(i) - 'a']++;
            }
            for (int i = 0; i < t.length(); i++) {
                freq[t.charAt(i) - 'a']--;
            }
            for (int i = 0; i < 26; i++) {
                if (freq[i] != 0) {
                    same = false;
                }
            }
        }
        System.out.println(same);
    }
}

