import java.util.*;

public class Main {
    static int sumLoop(int n) {
        int total = 0;
        for (int i = 1; i <= n; i++) total += i;
        return total;
    }

    static int sumRec(int n) {
        if (n == 0) return 0;
        return n + sumRec(n - 1);
