exercises.solution:
import java.util.*;

class Range {
    private int low;
    private int high;

    Range(int a, int b) {
        if (a <= b) {
            low = a;
            high = b;
        } else {
            low = b;
            high = a;
        }
    }

    int length() {
        return high - low;
    }

    boolean contains(int v) {
        return v >= low && v <= high;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Range r = new Range(sc.nextInt(), sc.nextInt());
        System.out.println(r.length());
        System.out.println(r.contains(sc.nextInt()));
    }
}

