import java.util.*;

class BankAccount {
    private int balance;
    private int applied;

    BankAccount(int opening) {
        if (opening < 0) this.balance = 0;
        else this.balance = opening;
    }

    void deposit(int amount) {
        if (amount > 0) {
            balance += amount;
            applied++;
        }
    }

    void withdraw(int amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            applied++;
        }
    }

    int getBalance() {
        return balance;
    }

    int getApplied() {
        return applied;
    }
}

