import java.util.*;

class Playlist {
    private int[] lengths;
    private int size;

    Playlist(int capacity) {
        this.lengths = new int[capacity];
        this.size = 0;
    }

    boolean add(int seconds) {
        if (seconds <= 0 || size == lengths.length) {
            return false;
        }
        lengths[size] = seconds;
        size = size + 1;
        return true;
    }

    int getSize() {
        return size;
    }

    int totalSeconds() {
        int total = 0;
        for (int i = 0; i < size; i++) {
            total += lengths[i];
        }
        return total;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int cap = sc.nextInt();
