class Range {
    private int lo;
    private int hi;

    Range(int lo, int hi) {
        if (lo <= hi) {
            this.lo = lo;
            this.hi = hi;
        } else {
            this.lo = hi;
            this.hi = lo;
        }
    }

    boolean setLo(int v) {
        if (v > hi) {
            return false;
        }
        lo = v;
        return true;
    }

    boolean setHi(int v) {
        if (v < lo) {
            return false;
        }
        hi = v;
        return true;
    }

    String describe() {
