        this.value = value;
    }

    int get() {
        return value;
    }

    Counter next() {
        return new Counter(value + 1);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        Counter start = new Counter(0);
        Counter cur = start;
        for (int i = 0; i < k; i++) {
            cur = cur.next();
        }
        System.out.println(cur.get());
        System.out.println(start.get());
    }
}

