abstract class Account {
    protected final String owner;
    protected final int balance;

    Account(String owner, int balance) {
        this.owner = owner;
        this.balance = balance;
    }

    abstract int fee();

    String summary() {
        return owner + " " + balance + " fee=" + fee() + " net=" + (balance - fee());
    }
}

class Basic extends Account {
    Basic(String owner, int balance) {
        super(owner, balance);
    }

    @Override
    int fee() {
        return 2;
    }
}

class Premium extends Account {
    Premium(String owner, int balance) {
        super(owner, balance);
    }

    @Override
    int fee() {
        return balance / 100;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int total = 0;
        for (int i = 0; i < n; i++) {
            int kind = sc.nextInt();
            String owner = sc.next();
            int balance = sc.nextInt();
            Account a;
            if (kind == 1) {
                a = new Basic(owner, balance);
            } else {
                a = new Premium(owner, balance);
            }
            System.out.println(a.summary());
            total += balance - a.fee();
        }
        System.out.println("total=" + total);
    }
}

