import java.util.*;

interface Codec {
    String encode(String s);

    String decode(String s);
}

abstract class SymmetricCodec implements Codec {
    @Override
    public String decode(String s) {
        return encode(s);
    }
}

class Rot13 extends SymmetricCodec {
    @Override
    public String encode(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append((char) ('a' + (c - 'a' + 13) % 26));
            } else if (c >= 'A' && c <= 'Z') {
                sb.append((char) ('A' + (c - 'A' + 13) % 26));
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}

class Flip extends SymmetricCodec {
    @Override
    public String encode(String s) {
        return new StringBuilder(s).reverse().toString();
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String which = sc.next();
        String word = sc.next();
        Codec c;
        if (which.equals("rot13")) {
            c = new Rot13();
        } else {
            c = new Flip();
        }
        String enc = c.encode(word);
        System.out.println(enc);
        System.out.println(c.decode(enc));
    }
}

