import java.util.*;

interface Switchable {
    void turnOn();

    void turnOff();

    boolean isOn();

    default String state() {
        return isOn() ? "on" : "off";
    }
}

abstract class Device implements Switchable {
    private final String name;
    private boolean on;

    Device(String name) {
        this.name = name;
    }

    String name() {
        return name;
    }

    @Override
    public void turnOn() {
        on = true;
    }

    @Override
    public void turnOff() {
        on = false;
    }

    @Override
    public boolean isOn() {
        return on;
    }

    abstract int draw();

    @Override
    public String toString() {
        return name + " " + state() + " " + draw();
    }
}

class Lamp extends Device {
    private final int watts;

    Lamp(String name, int watts) {
        super(name);
        this.watts = watts;
    }

    @Override
    int draw() {
        return isOn() ? watts : 0;
    }
}

class Heater extends Device {
    private final int watts;

    Heater(String name, int watts) {
        super(name);
        this.watts = watts;
    }

    @Override
    int draw() {
        return isOn() ? watts : 5;
    }
}

final class Room {
    private final Device[] devices;
    private int peak;

    Room(Device[] devices) {
        this.devices = devices;
        this.peak = totalDraw();
    }

    int totalDraw() {
        int total = 0;
        for (Device d : devices) {
            total += d.draw();
        }
        return total;
    }

    String turnOn(String name) {
        Device d = find(name);
        d.turnOn();
        record();
        return d.toString();
    }

    String turnOff(String name) {
        Device d = find(name);
        d.turnOff();
        record();
        return d.toString();
    }

    int peak() {
        return peak;
    }

    private Device find(String name) {
        for (Device d : devices) {
            if (d.name().equals(name)) {
                return d;
            }
        }
        return null;
    }

    private void record() {
        int total = totalDraw();
        if (total > peak) {
            peak = total;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Device[] devices = new Device[n];
        for (int i = 0; i < n; i++) {
            String kind = sc.next();
            String name = sc.next();
            int watts = sc.nextInt();
            if (kind.equals("heater")) {
                devices[i] = new Heater(name, watts);
            } else {
                devices[i] = new Lamp(name, watts);
            }
        }
        Room room = new Room(devices);
        int q = sc.nextInt();
        for (int i = 0; i < q; i++) {
            String op = sc.next();
            if (op.equals("on")) {
                System.out.println(room.turnOn(sc.next()));
            } else if (op.equals("off")) {
                System.out.println(room.turnOff(sc.next()));
            } else {
                System.out.println("draw=" + room.totalDraw());
            }
        }
        System.out.println("peak=" + room.peak());
    }
}

