exercises.solution:
import java.util.*;

interface Validator {
    boolean ok(String s);
}

class NotEmpty implements Validator {
    @Override
    public boolean ok(String s) {
        return s.length() > 0;
    }
}

class MaxLen implements Validator {
    private final int max;

    MaxLen(int max) {
        this.max = max;
    }

    @Override
    public boolean ok(String s) {
        return s.length() <= max;
    }
}

class Digits implements Validator {
    @Override
    public boolean ok(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (!Character.isDigit(s.charAt(i))) {
                return false;
            }
        }
        return true;
    }
}

class Form {
    private final Validator[] rules;

    Form(Validator[] rules) {
        this.rules = rules;
    }

    int passes(String s) {
        int k = 0;
        for (Validator v : rules) {
            if (v.ok(s)) {
                k++;
            }
        }
        return k;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int max = sc.nextInt();
        String s = sc.next();
        Validator[] rules = { new NotEmpty(), new MaxLen(max), new Digits() };
        System.out.println(new Form(rules).passes(s));
    }
}

