import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();

        int fallback = Integer.parseInt(sc.nextLine());
        int v;
        try {
            v = Integer.parseInt(s);
        } catch (NumberFormatException e) {
