import java.util.*;

class Store {
    private int stock;

    Store(int stock) {
        this.stock = stock;
    }

    int take(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("bad amount");
        }
        int taken = n;
        if (taken > stock) {
            taken = stock;
        }
        stock = stock - taken;
        return taken;
    }

    int stock() {
        return stock;
    }
}

public class Main {
    public static void main(String[] args) {
