        int limit = words.size();
        if (other.size() > limit) {
            limit = other.size();
        }
        for (int i = 0; i < limit; i++) {
            if (i < words.size()) {
                out.add(words.get(i));
            }
            if (i < other.size()) {
                out.add(other.get(i));
            }
        }
        System.out.println(out);
    }
}

