                    char open = stack.pop();
                    if (c == ')' && open != '(') {
                        ok = false;
                    }
                    if (c == ']' && open != '[') {
                        ok = false;
                    }
                    if (c == '}' && open != '{') {
                        ok = false;
                    }
                }
            }
        }
        if (!stack.isEmpty()) {
            ok = false;
        }
        System.out.println(ok);
    }
}

