public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<String> words = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            words.add(sc.next());
        }
        int k = sc.nextInt();
        Deque<String> recent = new ArrayDeque<>();
        for (String w : words) {
            recent.remove(w);
            recent.addFirst(w);
            if (recent.size() > k) {
                recent.removeLast();
            }
        }
        while (!recent.isEmpty()) {
            System.out.println(recent.pollFirst());
        }
    }
}

