    }
}

class BySalaryDesc implements Comparator<Employee> {
    @Override
    public int compare(Employee a, Employee b) {
        int bySal = Integer.compare(b.salary(), a.salary());
        if (bySal != 0) {
            return bySal;
        }
        return a.name().compareTo(b.name());
    }
}

class ByDept implements Comparator<Employee> {
    @Override
    public int compare(Employee a, Employee b) {
        int byDept = a.dept().compareTo(b.dept());
        if (byDept != 0) {
            return byDept;
        }
        return a.name().compareTo(b.name());
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Employee> staff = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            staff.add(new Employee(sc.next(), sc.next(), sc.nextInt()));
        }
        String mode = sc.next();
        if (mode.equals("name")) {
            staff.sort(new ByName());
        } else if (mode.equals("salary")) {
            staff.sort(new BySalaryDesc());
        } else {
            staff.sort(new ByDept());
        }
        for (Employee e : staff) {
            System.out.println(e);
        }
        Set<String> depts = new TreeSet<>();
        Map<String, Integer> totals = new TreeMap<>();
        for (Employee e : staff) {
            depts.add(e.dept());
            totals.put(e.dept(),
                totals.getOrDefault(e.dept(), 0) + e.salary());
        }
        System.out.println("departments=" + depts);
        String bestDept = "";
        int bestTotal = -1;
        for (Map.Entry<String, Integer> en : totals.entrySet()) {
            if (en.getValue() > bestTotal) {
                bestTotal = en.getValue();
                bestDept = en.getKey();
            }
        }
        System.out.println("top=" + bestDept + " " + bestTotal);
    }
}

