import java.util.*;

class Rec {
    private final String name;
    private final int group;
    private final int score;

    Rec(String name, int group, int score) {
        this.name = name;
        this.group = group;
        this.score = score;
    }

    String name() {
        return name;
    }

    int group() {
        return group;
    }

    int score() {
        return score;
    }
}

class ByAll implements Comparator<Rec> {
    @Override
    public int compare(Rec a, Rec b) {
        int byGroup = Integer.compare(a.group(), b.group());
        if (byGroup != 0) {
            return byGroup;
        }
        int byScore = Integer.compare(b.score(), a.score());
        if (byScore != 0) {
            return byScore;
        }
        return a.name().compareTo(b.name());
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Rec> recs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            recs.add(new Rec(sc.next(), sc.nextInt(), sc.nextInt()));
        }
        recs.sort(new ByAll());
        for (Rec r : recs) {
            System.out.println(r.name() + " " + r.group() + " " + r.score());
